function normalize(value) {
  return String(value ?? "").trim().toLowerCase().replace(/[._-]/g, " ").replace(/\s+/g, " ");
}

function safeArray(value) {
  return Array.isArray(value) ? value : [];
}

function safeText(value, fallback = "N/A") {
  if (value === null || value === undefined) return fallback;
  const text = String(value).trim();
  return text || fallback;
}

function numberValue(value, fallback = 0) {
  if (value === null || value === undefined) return fallback;
  const parsed = Number(String(value).replace(/[^0-9.]/g, ""));
  return Number.isFinite(parsed) ? parsed : fallback;
}

function safePhone(value) {
  if (value === null || value === undefined || String(value).trim() === "") return "N/A";
  let phone = String(value).trim().replace(/^'+/, "");
  if (phone.startsWith("=")) phone = phone.substring(1).trim();
  return "'" + phone;
}

// Read Current Item
const currentData = $input.first().json;
let ai = currentData.output && typeof currentData.output === "object" ? currentData.output : currentData;

let jd = {};
try {
  const jdData = $('AI JD Analyzer').first().json;
  jd = jdData.output && typeof jdData.output === "object" ? jdData.output : jdData;
} catch (error) {
  jd = {};
}

// Extract Candidates Data safely
const candidateName = safeText(ai.candidate_name, "N/A");
const email = safeText(ai.email, "N/A");
const phone = safePhone(ai.phone);
const experienceYears = numberValue(ai.experience_years, 0);
const education = safeText(ai.education, "Not Specified");
const certifications = safeArray(ai.certifications);
const primaryBackground = safeText(ai.primary_background, "N/A");
const primaryStackProficiency = safeText(ai.primary_stack_proficiency || ai.python_proficiency, "None");
const alternativeRole = safeText(ai.alternative_role_fit, "N/A");

// Read JD Requirements
const appliedRole = safeText(jd.role, "Python Backend Developer");
const minimumExperience = numberValue(jd.minimum_experience_years, 5);

function uniqueSkills(skills) {
  const result = [];
  for (const skill of safeArray(skills)) {
    const clean = safeText(skill, "");
    if (!clean) continue;
    if (!result.some(e => normalize(e) === normalize(clean))) {
      result.push(clean);
    }
  }
  return result;
}

const cleanRequiredSkills = uniqueSkills(jd.required_skills?.length ? jd.required_skills : ["Python", "FastAPI", "SQL", "REST APIs", "Docker", "AWS", "Git"]);
const cleanPreferredSkills = uniqueSkills(jd.preferred_skills?.length ? jd.preferred_skills : ["PostgreSQL", "AWS EC2", "AWS S3", "Linux", "CI/CD", "Backend Architecture"]);
const cleanCriticalSkills = uniqueSkills(jd.critical_skills?.length ? jd.critical_skills : ["Python", "FastAPI"]);

const skillAudit = safeArray(ai.skill_audit);

function findAuditItem(skillName) {

  const target =
    normalize(skillName);

  return skillAudit.find(item => {

    const itemSkill =
      normalize(item?.skill);

    return itemSkill === target;

  });

}

// 1. Audit Required Skills
const matchedSkills = [];
const partialSkills = [];
const missingSkills = [];
const skillEvidence = [];

for (const reqSkill of cleanRequiredSkills) {
  const auditItem = findAuditItem(reqSkill);
  const status = String(auditItem?.status || "MISSING").trim().toUpperCase();
  const evidence = safeText(auditItem?.evidence, `No evidence of ${reqSkill} found in the resume.`);

  skillEvidence.push(`${reqSkill}: ${status} — ${evidence}`);

  if (status === "MATCHED") matchedSkills.push(reqSkill);
  else if (status === "PARTIAL") partialSkills.push(reqSkill);
  else missingSkills.push(reqSkill);
}

// 2. Audit Critical Skills
const criticalGaps = [];
const partialCriticalSkills = [];
const matchedCriticalSkills = [];

for (const critSkill of cleanCriticalSkills) {
  const auditItem = findAuditItem(critSkill);
  const status = String(auditItem?.status || "MISSING").trim().toUpperCase();

  if (status === "MATCHED") matchedCriticalSkills.push(critSkill);
  else if (status === "PARTIAL") partialCriticalSkills.push(critSkill);
  else criticalGaps.push(critSkill);
}

// 3. Audit Preferred Skills
const preferredMatched = [];
const preferredPartial = [];
const preferredMissing = [];

for (const prefSkill of cleanPreferredSkills) {
  const auditItem = findAuditItem(prefSkill);
  const status = String(auditItem?.status || "MISSING").trim().toUpperCase();

  if (status === "MATCHED") preferredMatched.push(prefSkill);
  else if (status === "PARTIAL") preferredPartial.push(prefSkill);
  else preferredMissing.push(prefSkill);
}

// 4. Scoring Engine
const WEIGHT_REQUIRED = 50;
const WEIGHT_EXPERIENCE = 25;
const WEIGHT_CRITICAL = 15;
const WEIGHT_PREFERRED = 10;

// Required Skill Score
let requiredSkillScore = 0;
if (cleanRequiredSkills.length > 0) {
  const points = matchedSkills.length + (partialSkills.length * 0.5);
  requiredSkillScore = (points / cleanRequiredSkills.length) * WEIGHT_REQUIRED;
}

// Experience Score
let experienceScore = 0;
if (minimumExperience > 0) {
  experienceScore = Math.min(WEIGHT_EXPERIENCE, (experienceYears / minimumExperience) * WEIGHT_EXPERIENCE);
} else {
  experienceScore = WEIGHT_EXPERIENCE;
}

// Critical Score
let criticalScore = 0;
if (cleanCriticalSkills.length > 0) {
  const points = matchedCriticalSkills.length + (partialCriticalSkills.length * 0.5);
  criticalScore = (points / cleanCriticalSkills.length) * WEIGHT_CRITICAL;
} else {
  criticalScore = WEIGHT_CRITICAL;
}

// Preferred Score
let preferredScore = 0;
if (cleanPreferredSkills.length > 0) {
  const points = preferredMatched.length + (preferredPartial.length * 0.5);
  preferredScore = (points / cleanPreferredSkills.length) * WEIGHT_PREFERRED;
} else {
  preferredScore = WEIGHT_PREFERRED;
}

let overallScore = Math.round(requiredSkillScore + experienceScore + criticalScore + preferredScore);
overallScore = Math.max(0, Math.min(100, overallScore));

// 5. Decision Engine
let recommendation = "Hold";
let risk = "Medium";
const criticalGapCount = criticalGaps.length;

if (criticalGapCount >= 2) {
  recommendation = "Reject";
  risk = "High";
} else if (criticalGapCount === 1) {
  if (overallScore >= 65) {
    recommendation = "Interview";
    risk = "Medium";
  } else {
    recommendation = "Reject";
    risk = "High";
  }
} else {
  if (overallScore >= 85) {
    recommendation = "Strong Hire";
    risk = "Low";
  } else if (overallScore >= 70) {
    recommendation = "Interview";
    risk = "Medium";
  } else if (overallScore >= 55) {
    recommendation = "Hold";
    risk = "Medium";
  } else {
    recommendation = "Reject";
    risk = "High";
  }
}

// 6. Summary Build
const summaryParts = [];
if (matchedSkills.length > 0) summaryParts.push(`Strong evidence in ${matchedSkills.join(", ")}`);
if (partialSkills.length > 0) summaryParts.push(`Partial exposure in ${partialSkills.join(", ")}`);
if (missingSkills.length > 0) summaryParts.push(`Key gaps include ${missingSkills.join(", ")}`);
summaryParts.push(`${experienceYears} years of relevant experience against a ${minimumExperience}-year requirement`);

let decisionText = "";
if (recommendation === "Strong Hire") {
  decisionText = "The candidate shows strong alignment with core requirements.";
} else if (recommendation === "Interview") {
  decisionText = criticalGapCount > 0 
    ? `The profile justifies an interview, but ${criticalGaps.join(", ")} requires validation.`
    : "The candidate has enough relevant alignment to justify an interview.";
} else if (recommendation === "Hold") {
  decisionText = "The profile requires secondary review before proceeding.";
} else {
  decisionText = "The candidate lacks alignment with core requirements.";
}

const hrSummary = `${summaryParts.join(". ")}. Overall alignment score is ${overallScore}%. ${decisionText}`;
const interviewQuestions = safeArray(ai.interview_questions);
const formattedQuestions = interviewQuestions.length > 0 
  ? interviewQuestions.slice(0, 5).map((q, i) => `${i + 1}. ${String(q).trim()}`).join("\n") 
  : "N/A";

// Return Data
return [{
  json: {
    "Candidate": candidateName,
    "Email": email,
    "Phone": phone,
    "Experience": experienceYears > 0 ? `${experienceYears} Years` : "Not Specified",
    "Education": education,
    "Certifications": certifications.length > 0 ? certifications.join(", ") : "None",
    "Primary Background": primaryBackground,
    "Primary Stack Proficiency": primaryStackProficiency,
    "Matched Skills": matchedSkills.length > 0 ? matchedSkills.join(", ") : "None",
    "Partial Skills": partialSkills.length > 0 ? partialSkills.join(", ") : "None",
    "Missing Skills": missingSkills.length > 0 ? missingSkills.join(", ") : "None",
    "Critical Gaps": criticalGaps.length > 0 ? criticalGaps.join(", ") : "None",
    "Preferred Skills Matched": preferredMatched.length > 0 ? preferredMatched.join(", ") : "None",
    "Skill Evidence": skillEvidence.length > 0 ? skillEvidence.join(" | ") : "N/A",
    "Match Percentage": `${overallScore}%`,
    "Overall Score": overallScore,
    "Risk Level": risk,
    "Recommendation": recommendation,
    "Applied Role": appliedRole,
    "Alternative Role Fit": alternativeRole,
    "HR Decision Summary": hrSummary,
    "Interview Questions": formattedQuestions,
    "Status": "Pending HR Review",
    "Reviewed On": new Date().toISOString().split("T")[0]
  }
}];
